package blockbranch.realistic;
public class RiverBankCheck{public static void main(String[]a){for(long seed:new long[]{424242,1,-17}){var d=new DrainageNetwork(new TerrainShape(seed),seed);var c=new ClimateField(seed);int mud=0,sand=0;long before=1,after=1;for(int i=0;i<d.size();i++){if(i%23!=0||!d.river(i)||Math.abs(d.nodeX(i))>1700000||Math.abs(d.nodeZ(i))>1700000)continue;for(double t:new double[]{.2,.5,.8}){int x=(int)Math.round(d.edgeX(i,t)),z=(int)Math.round(d.edgeZ(i,t));var ch=d.channelAt(x,z);if(ch.edge()<0)continue;var axis=RoutedRiver.axis(d,x,z);for(double lat:new double[]{-1.3,-1.1,1.1,1.3}){int wx=(int)Math.round(x-axis[1]*ch.halfWidth()*lat),wz=(int)Math.round(z+axis[0]*ch.halfWidth()*lat);var old=d.sample(wx,wz);before=31*before+old.height();before=31*before+old.waterLevel();int code=RoutedRiver.bankCover(seed,wx,wz,d,c);if(code>0){if(code==13)mud++;else if(code==14)sand++;else throw new AssertionError("Unknown dry bank");if(old.waterLevel()!=DrainageNetwork.DRY||RoutedRiver.bankChannel(d,wx,wz).edge()<0||GravelRiverMargin.surfaceContains(wx,wz,(qx,qz)->GravelRiverMargin.site(d,qx,qz))||LowGradientSandyShore.surfaceContains(wx,wz,(qx,qz)->LowGradientSandyShore.site(d,qx,qz))||AlpineScree.surfaceContains(wx,wz,d::sample))throw new AssertionError("Dry-bank protected domains");}var now=d.sample(wx,wz);after=31*after+now.height();after=31*after+now.waterLevel();}}}if(before!=after||mud<20||sand<20)throw new AssertionError("Bank coverage/hydrology");System.out.println("RIVER_FINE_BANK seed="+seed+" mud="+mud+" sand="+sand+" fingerprint="+after);}System.out.println("DRY_FINE_BANK_PROTECTED_DOMAINS_HYDROLOGY_PASS");}}
